INSERT INTO stage_events (qid, title, summary, start_year, start_month, start_day, end_year, end_month, end_day, precision, display_date, importance, url) VALUES
  ('Q3442989', 'Battle of Bar', 'The Battle of Bar (Serbian Cyrillic: Битка код Бара, romanized: Bitka kod Bara) took place in 1042 or 1043, between the army of Stefan Vojislav, the Serbian ruler of Duklja, and Byzantine forces led by Michaelus Anastasii governor of Dyrrhachium and local Slavic vassals. The battle was actually an ambush on the Byzantine forces in the mountain gorge, which ended in the utter defeat of the Byzantine forces.', 1042, 10, 7, NULL, NULL, NULL, 'day', '7 October 1042', 41, 'https://en.wikipedia.org/wiki/Battle_of_Bar'),
  ('Q16259251', 'Siege of Cattaro', 'The siege of Cattaro was fought between a British Royal Naval detachment of Captain William Hoste and Montenegrin forces of Petar I Petrović-Njegoš respectively and the French garrison under the command of Jean-Joseph Gauthier of the mountain fortress of Cattaro (now Kotor, Montenegro). The siege lasted from 14 October 1813 to 3 January 1814 during the Adriatic campaign of the Napoleonic Wars when the French surrendered.', 1813, 10, 14, 1814, 1, 3, 'day', '14 October 1813 – 3 January 1814', 34, 'https://en.wikipedia.org/wiki/Siege_of_Cattaro'),
  ('Q3545065', 'Battle of Grahovac', 'The Battle of Grahovac took place in the eponymous village of Grahovac from 11 to 13 May 1858, when the Montenegrin Grand Duke Mirko Petrović-Njegoš led the army of Principality of Montenegro against the Ottomans, ending in a decisive Montenegrin victory. After the victory, the demarcation of the border between Montenegro and the Ottoman Bosnia Eyalet was finalised.', 1858, 4, 28, 1858, 5, 1, 'day', '28 April 1858 – 1 May 1858', 45, 'https://en.wikipedia.org/wiki/Battle_of_Grahovac'),
  ('Q16724471', 'Montenegrin–Ottoman War of 1861–62', 'The Montenegrin–Ottoman War (1861–1862) was a war between the Principality of Montenegro and the Ottoman Empire that took place between 1861 and 1862. The war ended and Montenegro had to acknowledge Ottoman suzerainty.', 1861, NULL, NULL, 1862, NULL, NULL, 'year', '1861–1862', 41, 'https://en.wikipedia.org/wiki/Montenegrin%E2%80%93Ottoman_War_(1861%E2%80%931862)'),
  ('Q286420', 'Battle of Fundina', 'The Battle of Fundina took place on 2 August 1876 in Fundina, a village in Kuči, Principality of Montenegro. The day had a religious importance, as being the St.', 1876, 8, 2, NULL, NULL, NULL, 'day', '2 August 1876', 39, 'https://en.wikipedia.org/wiki/Battle_of_Fundina'),
  ('Q2586933', 'Battle of Vučji Do', 'The Battle of Vučji Do was a major battle of the Montenegrin-Ottoman War of 1876-78 that took place on 18 July 1876 in Vučji Do, Montenegro, fought between the combined forces of Montenegrin and Eastern Herzegovinian tribes (battalions) against the Ottoman Army under Grand Vizier Ahmed Muhtar Pasha. The Montenegrin-Herzegovinian forces heavily defeated the Ottomans, and managed to capture two of their commanders.', 1876, 7, 18, NULL, NULL, NULL, 'day', '18 July 1876', 50, 'https://en.wikipedia.org/wiki/Battle_of_Vu%C4%8Dji_Do'),
  ('Q4513932', 'Montenegrin–Ottoman War of 1876–78', 'The Montenegrin–Ottoman War (Serbian Cyrillic: Црногорско-турски рат, romanized: Crnogorsko-turski rat, "Montenegrin-Turkish War"), also known in Montenegro as the Great War (Вељи рат, Velji rat), was fought between the Principality of Montenegro and the Ottoman Empire between 1876 and 1878. The war ended with Montenegrin victory and Ottoman defeat in the larger Russo-Turkish War of 1877–1878.', 1876, 6, 18, 1878, 2, 19, 'day', '18 June 1876 – 19 February 1878', 55, 'https://en.wikipedia.org/wiki/Montenegrin%E2%80%93Ottoman_War_(1876%E2%80%931878)'),
  ('Q1001069', 'Battle of Novšiće', 'The Battle of Novšiće (Serbian: Boj na Novšiću/Бој на Новшићу; Bitka na Novšićima/Битка на Новшићима, Albanian: Beteja e Nokshiqit) was a battle for control over Plav and Gusinje fought on 4 December 1879 between forces of the Principality of Montenegro led by Marko Miljanov and local pro-Ottoman forces which included irregulars of the League of Prizren, both commanded by Ali Pasha, the Kaymekam of Gusinje. The League of Prizren consisted mainly of Albanians from Plav and Gusinje in Scutari Vilayet and irregulars from Kosovo Vilayet.', 1879, 12, 4, NULL, NULL, NULL, 'day', '4 December 1879', 37, 'https://en.wikipedia.org/wiki/Battle_of_Nov%C5%A1i%C4%87e'),
  ('Q27860380', 'Battle of Ulcinj', 'The Battle of Ulcinj took place between the Ottoman forces of Dervish Pasha and Albanian irregulars in the year of 1880 at the region of Kodre, close to Gornja Klezna. The area of Plav and Gusinje had been ceded to the Principality of Montenegro, according to the decisions of the Treaty of Berlin (1878), but the Albanians fought against the annexation.', 1880, 11, 22, NULL, NULL, NULL, 'day', '22 November 1880', 34, 'https://en.wikipedia.org/wiki/Battle_of_Ulcinj_(1880)'),
  ('Q1778176', 'Battle of Antivari', 'The Battle of Antivari or Action off Antivari was a naval engagement between a large fleet of French and British warships and two ships of the Austro-Hungarian navy at the start of the First World War. The old Austrian protected cruiser SMS Zenta and the destroyer SMS Ulan were blockading the Montenegrin port of Antivari, when on 16 August 1914, they were surprised and cut off by a large Anglo-French force that had sortied into the Adriatic.', 1914, 8, 16, NULL, NULL, NULL, 'day', '16 August 1914', 43, 'https://en.wikipedia.org/wiki/Battle_of_Antivari'),
  ('Q2451530', 'Battle of Mojkovac', 'The Battle of Mojkovac was a World War I battle fought between 6 and 7 January 1916 near Mojkovac, in today''s Montenegro, between the armies of Austria-Hungary and the Kingdom of Montenegro. It ended with a decisive Montenegrin victory.', 1916, 1, 6, 1916, 1, 7, 'day', '6 January 1916 – 7 January 1916', 53, 'https://en.wikipedia.org/wiki/Battle_of_Mojkovac'),
  ('Q12747413', 'Šahovići massacre', 'The Šahovići massacre was a massacre of the Muslim population of the Yugoslav village of Šahovići (modern-day Tomaševo in Montenegro) and neighbouring villages in the region of the Lower Kolašin. It was committed on 9 and 10 November 1924 by a mob of 2,000 Orthodox Christian men from Kolašin and Bijelo Polje that sought revenge for the earlier murder of Boško Bošković, governor of the area.', 1924, 11, 10, NULL, NULL, NULL, 'day', '10 November 1924', 41, 'https://en.wikipedia.org/wiki/%C5%A0ahovi%C4%87i_massacre'),
  ('Q4087316', 'Battle of Pljevlja', 'The Battle of Pljevlja (1-2 December 1941), was a World War II attack in the Italian governorate of Montenegro by Yugoslav Partisans under the command of General Arso Jovanović and Colonel Bajo Sekulić, who led 4,000 Montenegrin Partisans against the Italian occupiers in the town of Pljevlja.', 1941, 12, 1, NULL, NULL, NULL, 'day', '1 December 1941', 37, 'https://en.wikipedia.org/wiki/Battle_of_Pljevlja'),
  ('Q3300974', 'Bar massacre', 'The Bar massacre (Albanian: Masakra e Tivarit) was a mass killings of ethnic Albanians from the Serbian province of Kosovo by Yugoslav Partisans in late March or early April 1945 in Bar, a municipality in Montenegro, at the end of World War II.', 1945, 3, 27, NULL, NULL, NULL, 'day', '27 March 1945', 45, 'https://en.wikipedia.org/wiki/Bar_massacre'),
  ('Q3505185', '1979 Montenegro earthquake', 'The 1979 Montenegro earthquake occurred on 15 April at 06:19 UTC with a moment magnitude of 6.9 and a maximum Mercalli intensity of X (Extreme). It was the most devastating earthquake in SR Montenegro, then part of Yugoslavia, and was mostly felt along the Montenegrin and Albanian coastline.', 1979, 4, 15, NULL, NULL, NULL, 'day', '15 April 1979', 56, 'https://en.wikipedia.org/wiki/1979_Montenegro_earthquake'),
  ('Q63078193', 'Regional Roaming Agreement', 'The Regional Roaming Agreement, formally the Agreement on the price reduction of the roaming services in public mobile communications networks in the Western Balkans region, regulates the imposition of roaming charges within the countries in the Western Balkans; Albania, Kosovo, Bosnia and Herzegovina, North Macedonia, Montenegro and Serbia. The agreement covers both the charges mobile network operators can impose on their subscribers for using telephone and data services outside of the network''s member state, and the wholesale rates networks can charge each other to allow their subscribers…', 2019, 4, 4, NULL, NULL, NULL, 'day', '4 April 2019', 41, 'https://en.wikipedia.org/wiki/Regional_Roaming_Agreement'),
  ('Q86458103', 'COVID-19 pandemic in Europe', 'The global COVID-19 pandemic arrived in Europe with its first confirmed case in Bordeaux, France, on 24 January 2020, and subsequently spread widely across the continent. By 17 March 2020, every country in Europe had confirmed a case, and all have reported at least one death, with the exception of Vatican City.', 2020, 1, 24, NULL, NULL, NULL, 'day', '24 January 2020', 65, 'https://en.wikipedia.org/wiki/COVID-19_pandemic_in_Europe');
